def get_32x32_ints():
    """
    获取32x32方阵共1024个数字
    :return:
    """
    hex_str = ''
    c_bytes = bytes.fromhex(hex_str)
    key = 291
    nums = []
    for i in range(0, len(c_bytes), 4):
        c = int.from_bytes(c_bytes[i:i + 4], 'little', signed=False)
        n = c ^ key
        nums.append(n)
    return nums


def go_and_get_max_val(nums, nums_size):
    """
    遍历32x32方格，每个方格处的累加值只有2个来源：左边+当前值、上边+当前值。
    取大值，贪心算法即可得到结果
    :param nums: nums_size x nums_size 方格
    :param nums_size: 方格边长
    :return: 每个方格处的累加值
    """
    acc = [None for _ in range(1024)]
    acc[0] = (nums[0], 'start')  # 起点start

    for row in range(nums_size):
        for col in range(nums_size):
            index = nums_size * row + col
            temp_up, temp_left = None, None
            if row - 1 >= 0:
                temp_up = acc[nums_size * (row - 1) + col][0] + nums[index]  # 上边+当前值
            if col - 1 >= 0:
                temp_left = acc[nums_size * row + col - 1][0] + nums[index]  # 左边+当前值

            if temp_up and temp_left:  # 取大值，贪心算法
                if temp_up > temp_left:
                    acc[index] = (temp_up, 'up')
                else:
                    acc[index] = (temp_left, 'left')
            elif temp_up and not temp_left:
                acc[index] = (temp_up, 'up')
            elif not temp_up and temp_left:
                acc[index] = (temp_left, 'left')
            else:
                continue
    return acc


def get_path(acc, nums_size):
    row, col = nums_size - 1, nums_size - 1
    op = acc[nums_size * row + col][1]
    ops = []
    while op != 'start':  # 回溯找到操作
        if op == 'left':
            ops.append('1')
            col -= 1
        elif op == 'up':
            ops.append('2')
            row -= 1
        op = acc[32 * row + col][1]
    ops.reverse()  # 因为是回溯，所以要反转一下变正向
    return ''.join(ops)


if __name__ == '__main__':
    nums_size = 32  # 方格边长32
    nums = get_32x32_ints()

    acc = go_and_get_max_val(nums, 32)
    end = acc[nums_size * (nums_size - 1) + (nums_size - 1)]
    print(end, hex(end[0]))
    # (47077, 'left') 0xb7e5

    path = get_path(acc, nums_size)
    print(f'qsnctf{{{path}}}')
    # qsnctf{21112122121122222221222221122111211111222112211112111222122111}
